export type NotificationPriority = "low" | "normal" | "high" | "critical";

export interface NotificationAction {
  label: string;
  onClick: () => void;
}

export interface NotificationInput {
  /** Groups this notification with others sharing the same key (e.g. "comments:post-42"). */
  groupKey?: string;
  /** Used for the default groupBy="type" strategy and for consumer-side icon/color mapping. */
  type: string;
  title: string;
  message?: string;
  priority?: NotificationPriority;
  /** ms until auto-dismiss from the toast surface. null = persists until manually dismissed. */
  ttl?: number | null;
  actions?: NotificationAction[];
  /** If provided, an Undo action is shown; calling it fires this and removes the toast. */
  undo?: () => void;
  /** Arbitrary consumer payload for custom rendering. */
  data?: unknown;
}

export interface Notification extends NotificationInput {
  id: string;
  createdAt: number;
  read: boolean;
  undone?: boolean;
}

export type GroupByStrategy = "type" | "groupKey" | "none";

export interface NotificationConfig {
  /** Max number of toast groups visible at once. Default 3. */
  maxVisibleToasts?: number;
  /** Default ttl (ms) applied when a notification doesn't specify one. Default 5000. */
  defaultTtl?: number;
  /** How toasts are grouped/stacked. Default "groupKey" (falls back to type if no groupKey given). */
  groupBy?: GroupByStrategy;
  /** Max history length retained for the inbox. Default 200. */
  maxHistory?: number;
  /** Corner the toast viewport renders in. Default "bottom-right". */
  toastPosition?: "top-left" | "top-right" | "bottom-left" | "bottom-right";
}

export interface ToastGroupState {
  groupKey: string;
  type: string;
  /** Notification ids in this group, oldest first. */
  ids: string[];
  priority: NotificationPriority;
  expiresAt: number | null;
  /** Duration (ms) of the current running phase — used to compute progress-bar ratio. */
  durationMs: number | null;
  paused: boolean;
  remainingMs: number | null;
}

export interface NotificationContextValue {
  history: Notification[];
  toastOrder: string[];
  toastGroups: Record<string, ToastGroupState>;
  unreadCount: number;
  config: Required<NotificationConfig>;

  notify: (input: NotificationInput) => string;
  dismissToast: (groupKey: string) => void;
  dismissAllToasts: () => void;
  undo: (id: string) => void;
  pauseToast: (groupKey: string) => void;
  resumeToast: (groupKey: string) => void;

  markRead: (id: string) => void;
  markAllRead: () => void;
  clearHistory: () => void;
  removeFromHistory: (id: string) => void;
}

"use client";

import * as React from "react";
import type { NotificationContextValue } from "./types";

export const NotificationCtx = React.createContext<NotificationContextValue | null>(null);

export function useNotificationCtx(): NotificationContextValue {
  const ctx = React.useContext(NotificationCtx);
  if (!ctx) throw new Error("useNotificationCtx must be used inside NotificationRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { NotificationCtx } from "./notification-context";
import { useNotificationEngine } from "./use-notification-engine";
import { NotificationToastViewport } from "./notification-toast-viewport";
import type { NotificationConfig } from "./types";

export interface NotificationRootProps {
  config?: NotificationConfig;
  /**
   * Custom toast rendering. Receives the group's notification ids and the shared
   * dismiss/undo/pause/resume handlers already bound to that group.
   */
  renderToast?: React.ComponentProps<typeof NotificationToastViewport>["renderToast"];
  /** Mount the default toast viewport. Set false if you render your own via useNotifications(). */
  showToastViewport?: boolean;
  children: React.ReactNode;
}

/**
 * Mount once, high in the tree (e.g. root layout), so notification history and
 * active toasts persist across route changes for the lifetime of the session.
 */
export function NotificationRoot({
  config,
  renderToast,
  showToastViewport = true,
  children,
}: NotificationRootProps) {
  const ctx = useNotificationEngine(config);

  return (
    <NotificationCtx.Provider value={ctx}>
      {children}
      {showToastViewport && <NotificationToastViewport renderToast={renderToast} />}
    </NotificationCtx.Provider>
  );
}

NotificationRoot.displayName = "NotificationRoot";

"use client";

import * as React from "react";
import { useFloating, offset, flip, shift, autoUpdate } from "@floating-ui/react";
import { IconBell } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { useNotificationCtx } from "./notification-context";
import { NotificationItem } from "./notification-item";

export interface NotificationInboxProps {
  className?: string;
  panelClassName?: string;
}

/**
 * Bell icon + unread badge that opens a floating panel listing notification
 * history. Reads from the same NotificationRoot as the toast surface, so
 * history persists independently of which toasts are still visible.
 */
export function NotificationInbox({ className, panelClassName }: NotificationInboxProps) {
  const { history, unreadCount, markAllRead, clearHistory } = useNotificationCtx();
  const [open, setOpen] = React.useState(false);

  const { refs, floatingStyles } = useFloating({
    open,
    onOpenChange: setOpen,
    placement: "bottom-end",
    middleware: [offset(8), flip(), shift({ padding: 8 })],
    whileElementsMounted: autoUpdate,
  });

  React.useEffect(() => {
    if (!open) return;
    function onClick(e: MouseEvent) {
      const target = e.target as Node;
      const referenceEl = refs.reference.current;
      const referenceContains =
        referenceEl instanceof Element ? referenceEl.contains(target) : false;
      if (refs.floating.current?.contains(target) || referenceContains) return;
      setOpen(false);
    }
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open, refs.floating, refs.reference]);

  return (
    <>
      <button
        ref={refs.setReference}
        type="button"
        onClick={() => setOpen((p) => !p)}
        aria-label="Notifications"
        className={cn(
          "relative flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground",
          className,
        )}
      >
        <IconBell size={16} strokeWidth={1.8} />
        {unreadCount > 0 && (
          <span className="absolute right-1 top-1 flex h-3.5 min-w-3.5 items-center justify-center rounded-full bg-primary px-0.5 text-[9px] font-semibold text-primary-foreground">
            {unreadCount > 99 ? "99+" : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div
          ref={refs.setFloating}
          style={floatingStyles}
          className={cn(
            "z-50 flex w-80 max-w-[90vw] flex-col rounded-xl border border-border bg-card shadow-xl",
            panelClassName,
          )}
        >
          <div className="flex items-center justify-between border-b border-border/60 px-3 py-2.5">
            <span className="text-[12px] font-medium text-foreground">Notifications</span>
            <div className="flex items-center gap-3">
              {unreadCount > 0 && (
                <button
                  type="button"
                  onClick={markAllRead}
                  className="text-[11px] text-muted-foreground hover:text-foreground"
                >
                  Mark all read
                </button>
              )}
              {history.length > 0 && (
                <button
                  type="button"
                  onClick={clearHistory}
                  className="text-[11px] text-muted-foreground hover:text-foreground"
                >
                  Clear
                </button>
              )}
            </div>
          </div>

          <div className="max-h-96 overflow-y-auto p-1.5">
            {history.length === 0 ? (
              <p className="px-2 py-6 text-center text-[12px] text-muted-foreground/60">
                No notifications yet
              </p>
            ) : (
              history.map((n) => <NotificationItem key={n.id} notification={n} />)
            )}
          </div>
        </div>
      )}
    </>
  );
}

NotificationInbox.displayName = "NotificationInbox";

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useNotificationCtx } from "./notification-context";
import type { Notification } from "./types";

export interface NotificationItemProps {
  notification: Notification;
  className?: string;
}

const PRIORITY_DOT: Record<string, string> = {
  low: "bg-muted-foreground/40",
  normal: "bg-primary",
  high: "bg-amber-400",
  critical: "bg-red-500",
};

export function NotificationItem({ notification, className }: NotificationItemProps) {
  const { markRead, undo, removeFromHistory } = useNotificationCtx();

  return (
    <div
      onClick={() => !notification.read && markRead(notification.id)}
      className={cn(
        "group flex items-start gap-2.5 rounded-lg px-2.5 py-2.5 transition-colors",
        !notification.read && "bg-primary/[0.04]",
        "hover:bg-muted/60 cursor-default",
        className,
      )}
    >
      <span
        className={cn(
          "mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full",
          notification.read ? "bg-transparent" : PRIORITY_DOT[notification.priority ?? "normal"],
        )}
      />

      <div className="min-w-0 flex-1">
        <p className="truncate text-[13px] font-medium text-foreground">{notification.title}</p>
        {notification.message && (
          <p className="mt-0.5 line-clamp-2 text-[12px] text-muted-foreground">{notification.message}</p>
        )}

        <div className="mt-1 flex items-center gap-3">
          <span className="text-[10px] text-muted-foreground/60">{timeAgo(notification.createdAt)}</span>
          {notification.undo && !notification.undone && (
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                undo(notification.id);
              }}
              className="text-[11px] font-medium text-primary hover:underline"
            >
              Undo
            </button>
          )}
          {notification.undone && (
            <span className="text-[11px] text-muted-foreground/60 italic">Undone</span>
          )}
        </div>
      </div>

      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          removeFromHistory(notification.id);
        }}
        aria-label="Remove notification"
        className="shrink-0 text-[11px] text-muted-foreground/0 transition-colors group-hover:text-muted-foreground/50 hover:!text-foreground"
      >
        ✕
      </button>
    </div>
  );
}

NotificationItem.displayName = "NotificationItem";

function timeAgo(ts: number): string {
  const diff = Math.max(0, Date.now() - ts);
  const s = Math.floor(diff / 1000);
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

"use client";

import * as React from "react";
import { IconX } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { useNotificationCtx } from "./notification-context";
import type { ToastGroupState } from "./types";

export interface NotificationToastProps {
  group: ToastGroupState;
  className?: string;
}

const PRIORITY_ACCENT: Record<string, string> = {
  low: "bg-muted-foreground/40",
  normal: "bg-primary",
  high: "bg-amber-400",
  critical: "bg-red-500",
};

export function NotificationToast({ group, className }: NotificationToastProps) {
  const { history, dismissToast, pauseToast, resumeToast, undo } = useNotificationCtx();

  const latestId = group.ids[group.ids.length - 1];
  const latest = history.find((n) => n.id === latestId);
  const count = group.ids.length;

  // Progress bar: width animates from 100% to 0% over durationMs, restarting the
  // CSS transition whenever expiresAt changes (new item bumps the group, or resume).
  const [ready, setReady] = React.useState(false);
  React.useEffect(() => {
    setReady(false);
    const raf = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(raf);
  }, [group.expiresAt]);

  if (!latest) return null;

  return (
    <div
      role="status"
      onMouseEnter={() => pauseToast(group.groupKey)}
      onMouseLeave={() => resumeToast(group.groupKey)}
      className={cn(
        "relative w-80 max-w-[90vw] overflow-hidden rounded-xl border border-border",
        "bg-card/95 backdrop-blur shadow-lg",
        className,
      )}
    >
      <div className="flex items-start gap-3 p-3">
        <span
          className={cn("mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full", PRIORITY_ACCENT[group.priority] ?? PRIORITY_ACCENT.normal)}
        />

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <p className="truncate text-[13px] font-medium text-foreground">{latest.title}</p>
            {count > 1 && (
              <span className="shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
                {count}
              </span>
            )}
          </div>
          {latest.message && (
            <p className="mt-0.5 line-clamp-2 text-[12px] text-muted-foreground">{latest.message}</p>
          )}

          {(latest.actions?.length || latest.undo) && (
            <div className="mt-2 flex items-center gap-3">
              {latest.undo && (
                <button
                  type="button"
                  onClick={() => undo(latest.id)}
                  className="text-[11px] font-medium text-primary hover:underline"
                >
                  Undo
                </button>
              )}
              {latest.actions?.map((a) => (
                <button
                  key={a.label}
                  type="button"
                  onClick={a.onClick}
                  className="text-[11px] font-medium text-muted-foreground hover:text-foreground"
                >
                  {a.label}
                </button>
              ))}
            </div>
          )}
        </div>

        <button
          type="button"
          onClick={() => dismissToast(group.groupKey)}
          aria-label="Dismiss notification"
          className="shrink-0 rounded p-0.5 text-muted-foreground/50 transition-colors hover:text-foreground"
        >
          <IconX size={13} strokeWidth={1.8} />
        </button>
      </div>

      {group.durationMs !== null && (
        <div className="h-0.5 w-full bg-border/60">
          {group.paused && group.remainingMs !== null ? (
            <div
              className={cn("h-full", PRIORITY_ACCENT[group.priority] ?? PRIORITY_ACCENT.normal)}
              style={{ width: `${(group.remainingMs / group.durationMs) * 100}%` }}
            />
          ) : (
            <div
              className={cn("h-full", PRIORITY_ACCENT[group.priority] ?? PRIORITY_ACCENT.normal)}
              style={{
                width: ready ? "0%" : "100%",
                transitionProperty: "width",
                transitionTimingFunction: "linear",
                transitionDuration: ready ? `${group.durationMs}ms` : "0ms",
              }}
            />
          )}
        </div>
      )}
    </div>
  );
}

NotificationToast.displayName = "NotificationToast";

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useNotificationCtx } from "./notification-context";
import { NotificationToast } from "./notification-toast";
import type { ToastGroupState } from "./types";

export interface NotificationToastViewportProps {
  className?: string;
  renderToast?: (group: ToastGroupState) => React.ReactNode;
}

const POSITION_CLASSES: Record<string, string> = {
  "top-left": "top-4 left-4 items-start",
  "top-right": "top-4 right-4 items-end",
  "bottom-left": "bottom-4 left-4 items-start flex-col-reverse",
  "bottom-right": "bottom-4 right-4 items-end flex-col-reverse",
};

export function NotificationToastViewport({ className, renderToast }: NotificationToastViewportProps) {
  const { toastOrder, toastGroups, config } = useNotificationCtx();

  if (toastOrder.length === 0) return null;

  return (
    <div
      className={cn(
        "pointer-events-none fixed z-50 flex max-h-[100dvh] flex-col gap-2 p-4",
        POSITION_CLASSES[config.toastPosition] ?? POSITION_CLASSES["bottom-right"],
        className,
      )}
    >
      {toastOrder.map((groupKey) => {
        const group = toastGroups[groupKey];
        if (!group) return null;
        return (
          <div key={groupKey} className="pointer-events-auto">
            {renderToast ? renderToast(group) : <NotificationToast group={group} />}
          </div>
        );
      })}
    </div>
  );
}

NotificationToastViewport.displayName = "NotificationToastViewport";

import * as React from "react";
import type {
  Notification,
  NotificationConfig,
  NotificationContextValue,
  NotificationInput,
  ToastGroupState,
} from "./types";

const DEFAULT_CONFIG: Required<NotificationConfig> = {
  maxVisibleToasts: 3,
  defaultTtl: 5000,
  groupBy: "groupKey",
  maxHistory: 200,
  toastPosition: "bottom-right",
};

const PRIORITY_WEIGHT: Record<Notification["priority"] & string, number> = {
  low: 0,
  normal: 1,
  high: 2,
  critical: 3,
};

let _seq = 0;
function uid() {
  _seq += 1;
  return `ntf_${Date.now().toString(36)}_${_seq}`;
}

// ─── Reducer ──────────────────────────────────────────────────────────────────

interface EngineState {
  history: Notification[];
  toastOrder: string[]; // groupKeys, most-recently-active last
  toastGroups: Record<string, ToastGroupState>;
}

type Action =
  | { type: "ADD"; notification: Notification; groupKey: string; maxVisibleToasts: number; maxHistory: number }
  | { type: "REMOVE_TOAST_GROUP"; groupKey: string }
  | { type: "CLEAR_TOASTS" }
  | {
      type: "SET_GROUP_TIMING";
      groupKey: string;
      expiresAt: number | null;
      durationMs: number | null;
      paused: boolean;
      remainingMs: number | null;
    }
  | { type: "MARK_UNDONE"; id: string }
  | { type: "MARK_READ"; id: string }
  | { type: "MARK_ALL_READ" }
  | { type: "CLEAR_HISTORY" }
  | { type: "REMOVE_HISTORY_ITEM"; id: string };

function pickEvictionCandidate(
  toastOrder: string[],
  toastGroups: Record<string, ToastGroupState>,
): string | null {
  if (toastOrder.length === 0) return null;
  // Prefer lowest priority, then oldest (earliest in toastOrder = least recently active).
  let best: string | null = null;
  let bestWeight = Infinity;
  let bestIndex = Infinity;
  toastOrder.forEach((key, idx) => {
    const g = toastGroups[key];
    if (!g) return;
    const w = PRIORITY_WEIGHT[g.priority] ?? 1;
    if (w < bestWeight || (w === bestWeight && idx < bestIndex)) {
      best = key;
      bestWeight = w;
      bestIndex = idx;
    }
  });
  return best;
}

function reducer(state: EngineState, action: Action): EngineState {
  switch (action.type) {
    case "ADD": {
      const { notification, groupKey, maxVisibleToasts, maxHistory } = action;

      const history = [notification, ...state.history].slice(0, maxHistory);

      let { toastOrder, toastGroups } = state;
      const existing = toastGroups[groupKey];

      if (existing) {
        toastGroups = {
          ...toastGroups,
          [groupKey]: {
            ...existing,
            ids: [...existing.ids, notification.id],
            priority: notification.priority ?? existing.priority,
          },
        };
        // Bump to most-recently-active.
        toastOrder = [...toastOrder.filter((k) => k !== groupKey), groupKey];
      } else {
        let nextOrder = toastOrder;
        let nextGroups = toastGroups;

        if (nextOrder.length >= maxVisibleToasts) {
          const evictKey = pickEvictionCandidate(nextOrder, nextGroups);
          if (evictKey) {
            nextOrder = nextOrder.filter((k) => k !== evictKey);
            const { [evictKey]: _drop, ...rest } = nextGroups;
            nextGroups = rest;
          }
        }

        const newGroup: ToastGroupState = {
          groupKey,
          type: notification.type,
          ids: [notification.id],
          priority: notification.priority ?? "normal",
          expiresAt: null,
          durationMs: null,
          paused: false,
          remainingMs: null,
        };

        toastOrder = [...nextOrder, groupKey];
        toastGroups = { ...nextGroups, [groupKey]: newGroup };
      }

      return { history, toastOrder, toastGroups };
    }

    case "REMOVE_TOAST_GROUP": {
      const { [action.groupKey]: _drop, ...rest } = state.toastGroups;
      return {
        ...state,
        toastOrder: state.toastOrder.filter((k) => k !== action.groupKey),
        toastGroups: rest,
      };
    }

    case "CLEAR_TOASTS":
      return { ...state, toastOrder: [], toastGroups: {} };

    case "SET_GROUP_TIMING": {
      const g = state.toastGroups[action.groupKey];
      if (!g) return state;
      return {
        ...state,
        toastGroups: {
          ...state.toastGroups,
          [action.groupKey]: {
            ...g,
            expiresAt: action.expiresAt,
            durationMs: action.durationMs,
            paused: action.paused,
            remainingMs: action.remainingMs,
          },
        },
      };
    }

    case "MARK_UNDONE":
      return {
        ...state,
        history: state.history.map((n) => (n.id === action.id ? { ...n, undone: true } : n)),
      };

    case "MARK_READ":
      return {
        ...state,
        history: state.history.map((n) => (n.id === action.id ? { ...n, read: true } : n)),
      };

    case "MARK_ALL_READ":
      return { ...state, history: state.history.map((n) => ({ ...n, read: true })) };

    case "CLEAR_HISTORY":
      return { ...state, history: [] };

    case "REMOVE_HISTORY_ITEM":
      return { ...state, history: state.history.filter((n) => n.id !== action.id) };

    default:
      return state;
  }
}

// ─── Engine hook ──────────────────────────────────────────────────────────────

export function useNotificationEngine(configProp: NotificationConfig = {}): NotificationContextValue {
  const config: Required<NotificationConfig> = { ...DEFAULT_CONFIG, ...configProp };

  const [state, dispatch] = React.useReducer(reducer, {
    history: [],
    toastOrder: [],
    toastGroups: {},
  });

  // Timers live outside React state — they're an implementation detail of the engine.
  const timers = React.useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  const clearTimer = React.useCallback((groupKey: string) => {
    const t = timers.current.get(groupKey);
    if (t) {
      clearTimeout(t);
      timers.current.delete(groupKey);
    }
  }, []);

  const scheduleTimer = React.useCallback(
    (groupKey: string, ms: number) => {
      clearTimer(groupKey);
      const handle = setTimeout(() => {
        dispatch({ type: "REMOVE_TOAST_GROUP", groupKey });
        timers.current.delete(groupKey);
      }, ms);
      timers.current.set(groupKey, handle);
    },
    [clearTimer],
  );

  React.useEffect(() => {
    const map = timers.current;
    return () => {
      map.forEach((t) => clearTimeout(t));
      map.clear();
    };
  }, []);

  const notify = React.useCallback(
    (input: NotificationInput): string => {
      const id = uid();
      const priority = input.priority ?? "normal";
      const ttl = input.ttl === undefined ? config.defaultTtl : input.ttl;

      const notification: Notification = {
        ...input,
        id,
        priority,
        ttl,
        createdAt: Date.now(),
        read: false,
      };

      const groupKey =
        config.groupBy === "none"
          ? id
          : config.groupBy === "type"
          ? input.type
          : input.groupKey ?? input.type;

      dispatch({
        type: "ADD",
        notification,
        groupKey,
        maxVisibleToasts: config.maxVisibleToasts,
        maxHistory: config.maxHistory,
      });

      if (ttl !== null) {
        scheduleTimer(groupKey, ttl);
        dispatch({
          type: "SET_GROUP_TIMING",
          groupKey,
          expiresAt: Date.now() + ttl,
          durationMs: ttl,
          paused: false,
          remainingMs: null,
        });
      } else {
        clearTimer(groupKey);
        dispatch({
          type: "SET_GROUP_TIMING",
          groupKey,
          expiresAt: null,
          durationMs: null,
          paused: false,
          remainingMs: null,
        });
      }

      return id;
    },
    [config.defaultTtl, config.groupBy, config.maxHistory, config.maxVisibleToasts, scheduleTimer, clearTimer],
  );

  const dismissToast = React.useCallback(
    (groupKey: string) => {
      clearTimer(groupKey);
      dispatch({ type: "REMOVE_TOAST_GROUP", groupKey });
    },
    [clearTimer],
  );

  const dismissAllToasts = React.useCallback(() => {
    timers.current.forEach((t) => clearTimeout(t));
    timers.current.clear();
    dispatch({ type: "CLEAR_TOASTS" });
  }, []);

  const undo = React.useCallback(
    (id: string) => {
      const notification = state.history.find((n) => n.id === id);
      notification?.undo?.();
      dispatch({ type: "MARK_UNDONE", id });

      // Remove the id's group from the active toast surface if it's the sole/last member.
      for (const [groupKey, group] of Object.entries(state.toastGroups)) {
        if (group.ids.includes(id)) {
          clearTimer(groupKey);
          dispatch({ type: "REMOVE_TOAST_GROUP", groupKey });
          break;
        }
      }
    },
    [state.history, state.toastGroups, clearTimer],
  );

  const pauseToast = React.useCallback(
    (groupKey: string) => {
      const g = state.toastGroups[groupKey];
      if (!g || g.paused || g.expiresAt === null) return;
      clearTimer(groupKey);
      const remainingMs = Math.max(0, g.expiresAt - Date.now());
      dispatch({
        type: "SET_GROUP_TIMING",
        groupKey,
        expiresAt: null,
        durationMs: g.durationMs,
        paused: true,
        remainingMs,
      });
    },
    [state.toastGroups, clearTimer],
  );

  const resumeToast = React.useCallback(
    (groupKey: string) => {
      const g = state.toastGroups[groupKey];
      if (!g || !g.paused || g.remainingMs === null) return;
      scheduleTimer(groupKey, g.remainingMs);
      dispatch({
        type: "SET_GROUP_TIMING",
        groupKey,
        expiresAt: Date.now() + g.remainingMs,
        durationMs: g.remainingMs,
        paused: false,
        remainingMs: null,
      });
    },
    [state.toastGroups, scheduleTimer],
  );

  const markRead = React.useCallback((id: string) => dispatch({ type: "MARK_READ", id }), []);
  const markAllRead = React.useCallback(() => dispatch({ type: "MARK_ALL_READ" }), []);
  const clearHistory = React.useCallback(() => dispatch({ type: "CLEAR_HISTORY" }), []);
  const removeFromHistory = React.useCallback(
    (id: string) => dispatch({ type: "REMOVE_HISTORY_ITEM", id }),
    [],
  );

  const unreadCount = React.useMemo(
    () => state.history.reduce((n, item) => n + (item.read ? 0 : 1), 0),
    [state.history],
  );

  return {
    history: state.history,
    toastOrder: state.toastOrder,
    toastGroups: state.toastGroups,
    unreadCount,
    config,
    notify,
    dismissToast,
    dismissAllToasts,
    undo,
    pauseToast,
    resumeToast,
    markRead,
    markAllRead,
    clearHistory,
    removeFromHistory,
  };
}

import { useNotificationCtx } from "./notification-context";
import type { NotificationInput } from "./types";

/**
 * Call from anywhere under <NotificationRoot> to push a notification.
 * Returns the same context API — notify(), dismissToast(), undo(), etc. —
 * so consumers rarely need anything beyond this one hook.
 */
export function useNotifications() {
  const ctx = useNotificationCtx();

  function notify(input: NotificationInput): string {
    return ctx.notify(input);
  }

  return { ...ctx, notify };
}

